const intent=$json.intent;
const securityFlag=$json.security?.security_decision==='block'||$json.security?.security_decision==='escalate'||intent==='security_suspicion';
const reasons={
complaint:'customer_complaint',
payment_dispute:'payment_dispute',
human_request:'human_requested_handoff',
safety:'safety_issue',
security_suspicion:'security_issue',
};
const reason=securityFlag?'security_issue':(reasons[intent]||$json.reason||'manual_escalation');
return [{json:{...$json,escalation_reason:reason,security_priority:securityFlag}}];

const t=String($json.text||'').toLocaleLowerCase();
const severityRules=[
['critical',/(immediate danger|life threatening|medical emergency|fire|explosion|weapon|self.?harm|threat.*violence|hack.*account|account.*takeover)/i],
['high',/(fraud|unauthori[sz]ed payment|chargeback|legal|lawyer|police|court|stolen|data leak|privacy breach|security incident)/i],
['medium',/(angry|complaint|refund dispute|damaged|defective|human agent|manager)/i]
];
let severity='medium';
for(const [s,re] of severityRules){if(re.test(t)){severity=s;break;}}
if($json.security_priority) severity='high';
return [{json:{...$json,severity}}];

const state=$json.state||{};
const count=Number(state.escalation_count||0);
const open=state.escalation_status==='OPEN';
return [{json:{...$json,previous_escalations:count,existing_escalation_open:open,repeat_escalation:open||count>0}}];

const i=$json.identity||{};
const identityLevel=i.level||'anonymous';
const fields={
channel_user_id:i.channel_user_id||null,
customer_id:i.customer_id||null,
identity_level:identityLevel
};
return [{json:{...$json,identity_summary:fields}}];

const context={
message_id:$json.message_id,
conversation_id:$json.conversation_id,
intent:$json.intent,
reason:$json.escalation_reason,
severity:$json.severity,
identity:$json.identity_summary,
current_stage:$json.state?.stage||'UNKNOWN',
selected_product_id:$json.state?.selected_product_id||null,
cart_id:$json.state?.cart_id||null,
repeat_escalation:$json.repeat_escalation
};
const disallowedKeys=['password','otp','cvv','cvc','card_number','api_key','token','system_prompt','developer_prompt'];
for(const k of disallowedKeys) delete context[k];
return [{json:{...$json,escalation_context:context}}];

const responsePolicy=$json.severity==='critical'
?'Acknowledge briefly, state that a human specialist is being engaged, and do not provide speculative instructions.'
:$json.severity==='high'
?'Acknowledge the issue, avoid unsupported conclusions, and state that a specialist will review it.'
:'Acknowledge the request and explain that the conversation is being handed to a human specialist.';
return [{json:{...$json,customer_response_policy:responsePolicy,tools_allowed:false,execution_allowed:false,llm_allowed:true}}];
